import express from 'express';
import type { Row } from './model';

interface OrdersView { title: string; rows: Row[] }

const app = express();
app.set('view engine', 'ejs');

app.get('/orders', (req, res) => {
  const view: OrdersView = { title: 'Orders', rows: [] };
  res.render('orders', view);   // EJS escapes with <%=, not with <%- 
});
